// #10455 (a) — the per-session seccomp artifact selector (ADR-075 addendum 2026-10-19).
//
// Two artifacts are baked into the runner image (infra/bwrap-userns-clone3-{deny,unixdeny}.bpf, both
// generated by scripts/gen-bwrap-userns-seccomp.mjs). The bwrap PATH shim loads whichever file
// SOLEUR_BWRAP_SECCOMP_BPF names:
//   - base:      nested-userns / clone3 deny. Every session that has any egress stays on it, because the
//                SDK's in-sandbox `socat ... UNIX-CONNECT` proxy bridges need socket(AF_UNIX).
//   - unixdeny:  base + socket(AF_UNIX) -> EPERM. NO-EGRESS sessions only, and only while the runtime
//                flag `agent-sandbox-unix-deny` is ON (default OFF = base = today's posture).
//
// `usesUnixDenyArtifact` is the single predicate; `seccompArtifactFor` the single path resolver.
// `buildAgentEnv` (the selector env var) and `buildAgentSandboxConfig` (the session posture it
// records) both feed them the same inputs, and `checkSeccompAgreement` re-checks the pair at spawn
// time; it never throws (the caller mirrors the disagreement to Sentry and corrects toward the base
// artifact, see agent-runner-query-options.ts). It is a leaf module on purpose:
// agent-env.ts cannot import agent-runner-sandbox-config.ts (that file imports agent-env.ts).

import { realpathSync } from "node:fs";
import { resolve as resolvePath } from "node:path";

/** Baked default of the base artifact (Dockerfile COPY); the shim's own default is the same path. */
export const SECCOMP_BASE_ARTIFACT = "/app/infra/bwrap-userns-clone3-deny.bpf";
/** Baked path of the AF_UNIX-deny variant (Dockerfile COPY). */
export const SECCOMP_UNIXDENY_ARTIFACT = "/app/infra/bwrap-userns-clone3-unixdeny.bpf";
/** The env var the shim (and the C4 prelude) reads to pick the artifact. */
export const SECCOMP_SELECTOR_ENV = "SOLEUR_BWRAP_SECCOMP_BPF";
/** Test/incident override for the variant path (the probe and the dev box have no /app). */
const SECCOMP_UNIXDENY_OVERRIDE_ENV = "SOLEUR_BWRAP_SECCOMP_BPF_UNIXDENY";

type Env = Record<string, string | undefined>;

/**
 * Do two selector values name the same artifact FILE? Compares resolved paths, not strings: an ambient override that
 * names a symlink or a `..` alias of the unixdeny artifact must be recognised as the unixdeny artifact. `realpath`
 * needs the file to exist; when it does not (the baked `/app/infra/...` path on a dev box) the lexically resolved
 * path is compared instead. A byte-for-byte COPY at a different path is not detectable this way.
 */
export function isSameArtifactPath(a: string | undefined, b: string | undefined): boolean {
  if (!a || !b) return false;
  return canonicalArtifactPath(a) === canonicalArtifactPath(b);
}

function canonicalArtifactPath(p: string): string {
  const resolved = resolvePath(p);
  try {
    return realpathSync(resolved);
  } catch {
    // review: swallowed on purpose - realpath needs the file to exist; a missing artifact (the baked /app path on a dev
    // box, or a mistyped override) falls back to the lexical path, and the comparison stays well-defined.
    return resolved;
  }
}

export function unixdenyArtifactPath(env: Env = process.env): string {
  return env[SECCOMP_UNIXDENY_OVERRIDE_ENV] || SECCOMP_UNIXDENY_ARTIFACT;
}

/**
 * Does this session get the AF_UNIX-deny artifact? Only a session with NO egress of any kind
 * (no GitHub egress, no web egress) while the runtime flag is on. `unixDenyFlag` defaults OFF so a
 * caller that forgets it keeps today's posture.
 */
export function usesUnixDenyArtifact(hasEgress: boolean, unixDenyFlag: boolean = false): boolean {
  return unixDenyFlag === true && hasEgress === false;
}

/**
 * The artifact path a session must be spawned with. For a session that does not use the variant
 * this is the BASE artifact: the ambient incident-time override if set, else the baked default
 * (buildAgentEnv leaves the ambient value untouched in that case).
 */
export function seccompArtifactFor(hasEgress: boolean, unixDenyFlag: boolean = false, env: Env = process.env): string {
  if (usesUnixDenyArtifact(hasEgress, unixDenyFlag)) return unixdenyArtifactPath(env);
  return env[SECCOMP_SELECTOR_ENV] || SECCOMP_BASE_ARTIFACT;
}

// The posture a sandbox config was built for. The SDK-bound config object cannot carry extra
// keys, so the pairing lives in a WeakMap keyed by the config itself.
export interface SandboxPosture {
  hasEgress: boolean;
  unixDenyFlag: boolean;
}
const POSTURES = new WeakMap<object, SandboxPosture>();

export function recordSandboxPosture<T extends object>(config: T, posture: SandboxPosture): T {
  POSTURES.set(config, posture);
  return config;
}

export function sandboxPostureOf(config: object): SandboxPosture | undefined {
  return POSTURES.get(config);
}

/**
 * Spawn-time check: do the env handed to the SDK and the sandbox config describe the SAME session?
 * Returns the disagreement text, or null when they agree. It NEVER throws: a throw at query start would
 * turn defense-in-depth into a total outage for every tenant that hits it (an incident-time
 * SOLEUR_BWRAP_SECCOMP_BPF override naming the unixdeny path is enough). The caller mirrors the text to
 * Sentry and corrects the selector toward the base artifact (today's posture). Disagreement is
 *   - the config was not built by buildAgentSandboxConfig (no recorded posture),
 *   - the env carries egress (GH_TOKEN / the credentialed proxy URL) that the config did not, or vice versa,
 *   - the env selects the unixdeny artifact for an egress session, or the base for a no-egress session
 *     whose flag is on.
 * `allowGithubEgress` / the web-egress handle are constant for the lifetime of a query: both builders
 * run once, in the same call, from the same arguments.
 */
export function checkSeccompAgreement(env: Env, sandbox: object, process_env: Env = process.env): string | null {
  const posture = sandboxPostureOf(sandbox);
  if (!posture) {
    return "agent-sandbox seccomp: sandbox config has no recorded posture (not built by buildAgentSandboxConfig)";
  }
  const envHasEgress = Boolean(env.GH_TOKEN) || Boolean(env.HTTPS_PROXY);
  if (envHasEgress !== posture.hasEgress) {
    return `agent-sandbox seccomp: egress disagreement (env hasEgress=${envHasEgress}, sandbox hasEgress=${posture.hasEgress})`;
  }
  const wantVariant = usesUnixDenyArtifact(posture.hasEgress, posture.unixDenyFlag);
  const selected = env[SECCOMP_SELECTOR_ENV];
  const variantPath = unixdenyArtifactPath(process_env);
  const gotVariant = isSameArtifactPath(selected, variantPath);
  if (gotVariant !== wantVariant) {
    return (
      `agent-sandbox seccomp: artifact disagreement (selector=${selected ?? "<unset>"}, ` +
      `expected ${wantVariant ? "the unixdeny artifact" : "a non-unixdeny artifact"} ` +
      `for hasEgress=${posture.hasEgress} flag=${posture.unixDenyFlag})`
    );
  }
  return null;
}
